function owner(t: Terms, x: Ctx): void {
  const { protocol: o, guards: g } = x.s;
  t.bankrFeeBps = o.bankrFeeBps;
  t.bankrMinPips = o.bankrMinPips;
  t.holdersShareBps = o.holdersShareBps;
  t.takeover = (x.flags & F.takeover) !== 0n;
  [t.ctoNotice, t.ctoGrace] = [o.ctoNotice, o.ctoGrace];
  t.tokenActivationDivisor = o.tokenActivationDivisor;
  t.bnkrActivationDivisor = o.bnkrActivationDivisor;
  [t.minRoundTripPips, t.pool.refTauSecs] = [g.minRoundTripPips, g.refTauSecs];
}

function wiring(t: Terms, x: Ctx): void {
  const { quote: q, wiring: w } = x.s;
  const listed = q.terms.allowed;
  if (!listed) {
    flag(x, F.unlistedQuotes);
    if (!q.hasCode) revert("QuoteNotAllowed");
  }
  if (!q.padTakes) revert("QuoteNotAllowedByLaunchpad");
  hold(B.bankrV4QuoteSupplyBound(q.totalSupply));
  t.quoteActivation =
    q.terms.quoteActivation === 0n ? 1n : q.terms.quoteActivation;
  [t.hook, t.holderLeg, t.legId] = [w.hook, w.holderLeg, w.legId];
  t.holderConverts = w.legConverts;
  const quoteIsBnkr = isAddressEqual(t.quote, w.bnkr);
  hold(
    B.bankrV4QuoteRouteBound({
      quote: t.quote,
      listed,
      legConverts: w.legConverts,
      legPaysInQuote: w.legPaysInQuote,
      quoteIsBnkr,
      quotePaid: q.terms.quotePaid,
    }),
  );
  t.waiveBnkrPair = !isZero(w.bnkr) && quoteIsBnkr && x.s.padWaiver;
}

function supplyAndVest(p: Params, t: Terms, x: Ctx): void {
  let supply = p.totalSupply;
  const whole = range(x, K.supply);
  if (supply === 0n) supply = whole.dflt * WAD;
  else if (supply < whole.min * WAD || supply > whole.max * WAD) {
    revert("OutsideLaunchpadRange", K.supply, whole.min, whole.max);
  }
  const own = BigInt(p.vestBps);
  const toHolders = BigInt(p.econ.vestToHoldersBps);
  let vested = (supply * (own + toHolders)) / 10_000n;
  let alloc = 0n;
  if (p.extraAllocations.length !== 0) {
    flag(x, F.allocations);
    alloc = p.extraAllocations.reduce((sum, a) => sum + a.amount, 0n);
  }
  const vest = range(x, K.vestBps);
  if (
    own < vest.min ||
    own + (alloc * 10_000n + supply - 1n) / supply > vest.max
  ) {
    revert("OutsideLaunchpadRange", K.vestBps, vest.min, vest.max);
  }
  vested += alloc;
  const cliff = p.econ.vestToHoldersCliff;
  const dur = p.econ.vestToHoldersDuration;
  if (toHolders === 0n) {
    if ((cliff | dur) !== 0n) revert("InvalidVestToHolders");
  } else {
    pick(x, K.vestToHoldersBps, ALWAYS, toHolders);
    pick(x, K.vestToHoldersSecs, ALWAYS, dur);
    if (cliff > dur) revert("InvalidVestToHolders");
  }
  hold(B.bankrV4VestedBound({ supply, vested }));
  const all = range(x, K.vestedTotalBps);
  if (vested * 10_000n > supply * all.max) {
    revert("OutsideLaunchpadRange", K.vestedTotalBps, all.min, all.max);
  }
  [t.totalSupply, t.vestedAmount] = [supply, vested];
  [t.vestBps, t.vestToHoldersBps] = [p.vestBps, p.econ.vestToHoldersBps];
  [t.vestToHoldersCliff, t.vestToHoldersDuration] = [cliff, dur];
  if (own === 0n) return unset(x, O.OPT_VEST_CLOCK);
  t.vestCliffSecs = Number(
    pick(x, K.vestCliffSecs, O.OPT_VEST_CLOCK, x.o.vestCliffSecs),
  );
  t.vestSecs = Number(pick(x, K.vestSecs, O.OPT_VEST_CLOCK, x.o.vestSecs));
}

function capAndSwitches(p: Params, t: Terms, x: Ctx): void {
  const secs = Number(pick(x, K.capSecs, O.OPT_CAP, x.o.capSecs));
  if (secs !== 0) {
    const bps = pick(x, K.capBps, O.OPT_CAP, x.o.capBps);
    t.capAmount = (t.totalSupply * bps) / 10_000n;
  }
  if (secs === 0 ? x.o.capBps !== 0 : t.capAmount === 0n) {
    revert("HardBound", 11);
  }
  t.capSecs = secs;
  t.capController = x.pad.capController;
  const bytes = new TextEncoder().encode(p.metadataUri).length;
  t.metadataMaxBytes = Number(under(x, K.metadataBytes, bytes));
  t.devBuyMaxBps = Number(under(x, K.devBuyMaxBps, 0));
  if (!isZero(p.metadataAdmin)) flag(x, F.metadataAdmin);
  if (p.capExclusions.length !== 0) flag(x, F.capExclusions);
  const n = p.feeRecipients.length;
  const most = B.bankrV4MaxFeeRecipients({
    feeRecipients: n,
    takeover: t.takeover,
    knobMax: Number(under(x, K.feeRecipients, n)),
  });
  if (typeof most !== "number") return hold(most);
  t.maxFeeRecipients = most;
}

function schedule(x: Ctx, f: B.BankrV4FeeScheduleTerms): void {
  pick(x, K.steadyPips, ALWAYS, f.steadyPips);
  if (f.startPips !== f.steadyPips) pick(x, K.startPips, ALWAYS, f.startPips);
  pick(x, K.decaySecs, ALWAYS, f.decaySecs);
  hold(B.bankrV4FeeScheduleBound(f));
}

function fees(e: Params["econ"], t: Terms, x: Ctx): void {
  schedule(x, e.buy);
  schedule(x, e.sell);
  [t.pool.buy, t.pool.sell] = [{ ...e.buy }, { ...e.sell }];
  const referrer = Number(pick(x, K.referrerBps, ALWAYS, e.referrerBps));
  hold(
    B.bankrV4BankrCutBound({
      bankrFeeBps: t.bankrFeeBps,
      bankrMinPips: t.bankrMinPips,
      referrerBps: referrer,
      buySteadyPips: e.buy.steadyPips,
      sellSteadyPips: e.sell.steadyPips,
    }),
  );
  t.referrerBps = referrer;
  t.holdersBps = Number(pick(x, K.holdersBps, ALWAYS, e.holdersBps));
  t.autoLpBps = Number(pick(x, K.autoLpBps, ALWAYS, e.autoLpBps));
  t.buybackBps = Number(pick(x, K.buybackBps, ALWAYS, e.buybackBps));
  hold(B.bankrV4SplitsBound(t));
  t.pool.buyback = t.buybackBps !== 0;
  hold(
    B.bankrV4BuybackFeeBound({
      buyback: t.pool.buyback,
      buySteadyPips: e.buy.steadyPips,
      feeCeilingPips: 0,
    }),
  );
}

function payees(p: Params, t: Terms, x: Ctx): BankrV4PadConfig["terms"] {
  const pad = x.pad.terms;
  t.padTermsHash = bankrV4PadTermsHashOf(pad);
  if (
    BigInt(p.operatorPayeesHash) !== 0n &&
    p.operatorPayeesHash.toLowerCase() !== t.padTermsHash
  ) {
    revert("OperatorPayeesMismatch");
  }
  const steady = B.bankrV4PadSplit(pad.payees, pad.steadySharesWad);
  const decay = pad.decay.on
    ? B.bankrV4PadSplit(pad.payees, pad.decay.sharesWad)
    : { sum: 0n, rest: 0n };
  if (!steady || !decay) return revert("InvalidPayees");
  const most = steady.sum > decay.sum ? steady.sum : decay.sum;
  const limit = x.s.limits[K.padShareBps]!.max;
  if (
    pad.payees.length > x.s.protocol.maxPadPayees ||
    most > limit * 10n ** 14n
  ) {
    revert("InvalidPayees");
  }
  if (most > BigInt(p.maxOperatorShareBps) * 10n ** 14n) {
    revert("OperatorShareAboveLauncherBound");
  }
  x.kept = B.bankrV4KeptWad({
    padPayeesWad: steady.sum,
    referrerBps: t.referrerBps,
  });
  t.pool.creatorLp = B.bankrV4SharePaid(steady.rest, t.autoLpBps);
  t.pool.decayLp = B.bankrV4SharePaid(decay.rest, pad.decay.autoLpBps);
  hold(
    B.bankrV4DecayAutoLpBound({
      creatorLp: t.pool.creatorLp,
      decayLp: t.pool.decayLp,
      buyDecaySecs: t.pool.buy.decaySecs,
      sellDecaySecs: t.pool.sell.decaySecs,
    }),
  );
  x.lp = t.pool.creatorLp || t.pool.decayLp;
  entries(p.feeRecipients.length || 1, pad, t);
  return pad;
}

/** B18 on what the ledger counts: an upper bound, never under the ledger's own. */
function entries(n: number, pad: BankrV4PadConfig["terms"], t: Terms): void {
  const one = (on: boolean) => (on ? 1 : 0);
  let creator =
    n +
    one(t.holdersBps !== 0) +
    one(t.pool.creatorLp) +
    one(t.buybackBps !== 0);
  let decay = n + one(t.pool.decayLp);
  pad.payees.forEach((payee, at) => {
    if (isAddressEqual(payee, BANKR_V4_PAD_TREASURY_MARKER)) return;
    if (pad.steadySharesWad[at] !== 0n) creator += 1;
    if (pad.decay.on && pad.decay.sharesWad[at] !== 0n) decay += 1;
  });
  hold(
    B.bankrV4BucketEntriesBound({
      creatorEntries: creator,
      decayEntries: pad.decay.on ? decay : 0,
      takeover: t.takeover,
    }),
  );
}

function amounts(t: Terms, x: Ctx): void {
  const { terms: q, padAmounts: own } = x.s.quote;
  let floor: bigint;
  let cap: bigint;
  if ((x.set & O.OPT_COMPOUND_AMOUNTS) !== 0) {
    flag(x, F.launchCompoundAmounts);
    [floor, cap] = [x.o.compoundFloor, x.o.compoundCap];
  } else {
    [floor, cap] = own.own
      ? [own.compoundFloor, own.compoundCap]
      : [q.compoundFloor, q.compoundCap];
  }
  hold(
    B.bankrV4CompoundAmountsBound({ compoundFloor: floor, compoundCap: cap }),
  );
  [t.pool.compoundFloor, t.pool.compoundCap] = [floor, cap];
}

function works(t: Terms, x: Ctx): void {
  const g = x.s.guards;
  const cadence = O.OPT_COMPOUND_CADENCE;
  const steadies = {
    buySteadyPips: t.pool.buy.steadyPips,
    sellSteadyPips: t.pool.sell.steadyPips,
    keptWad: x.kept,
  };
  if (x.lp) {
    amounts(t, x);
    t.pool.compoundInterval = Number(
      pick(x, K.compoundIntervalSecs, cadence, x.o.compoundInterval),
    );
    t.pool.compoundShareBps = Number(
      pick(x, K.compoundShareBps, cadence, x.o.compoundShareBps),
    );
    const dev = Number(
      pick(x, K.compoundDeviationTicks, cadence, x.o.compoundDeviationTicks),
    );
    const half = Number(
      pick(x, K.bandHalfWidth, O.OPT_COMPOUND_BAND, x.o.bandHalfWidth),
    );
    t.pool.bandGrid = Number(
      pick(x, K.bandGrid, O.OPT_COMPOUND_BAND, x.o.bandGrid),
    );
    const cap = B.bankrV4CompoundSwapCap({
      ...steadies,
      compoundSwapMaxTicks: g.compoundSwapMaxTicks,
    });
    hold(
      B.bankrV4CompoundGateBound({
        deviationTicks: dev,
        halfWidthSpacings: half,
        swapCapTicks: cap,
      }),
    );
    [t.pool.compoundDeviationTicks, t.pool.bandHalfWidth] = [dev, half];
    t.pool.swapCapTicks = cap;
  } else {
    unset(x, O.OPT_COMPOUND_AMOUNTS | cadence | O.OPT_COMPOUND_BAND);
  }
  if (!t.pool.buyback) return unset(x, O.OPT_BUYBACK_CADENCE);
  hold(
    B.bankrV4BuybackRoundTripBound({
      ...steadies,
      minRoundTripPips: g.minRoundTripPips,
    }),
  );
  t.pool.buybackInterval = Number(
    pick(x, K.buybackIntervalSecs, O.OPT_BUYBACK_CADENCE, x.o.buybackInterval),
  );
  t.pool.buybackRetry = Number(
    pick(x, K.buybackRetrySecs, O.OPT_BUYBACK_CADENCE, x.o.buybackRetry),
  );
  t.pool.fillTravelTicks = x.lp
    ? g.fillTravelCompoundingTicks
    : g.fillTravelTicks;
  t.pool.fillStartGapTicks = g.fillStartGapTicks;
  hold(B.bankrV4FillTravelBound({ compounds: x.lp, ...g }));
}

function stream(t: Terms, x: Ctx): void {
  const bit = O.OPT_REWARD_STREAM;
  t.rewardStreamSecs = Number(
    pick(x, K.rewardStreamSecs, bit, x.o.rewardStreamSecs),
  );
  t.rewardRestartBps = Number(
    pick(x, K.rewardRestartBps, bit, x.o.rewardRestartBps),
  );
  hold(
    B.bankrV4ClocksBound({
      start: t.startTime === 0n ? x.s.now : t.startTime,
      vestToHoldersCliff: t.vestToHoldersCliff,
      vestToHoldersDuration: t.vestToHoldersDuration,
      rewardStreamSecs: t.rewardStreamSecs,
      capSecs: t.capSecs,
    }),
  );
}

/**
 * `settings.resolve(launcher, nativeDevBuy, params)` over `state`: the terms the launch would freeze, their hash
 * and the pad's payees. Throws BankrV4ResolveRevert with the chain's own error where the chain reverts.
 */
export function resolveBankrV4Launch(
  state: BankrV4ResolverState,
  i: { launcher: Address; nativeDevBuy: bigint; params: BankrV4ResolveParams },
): BankrV4ResolvedTerms {
  const p = i.params;
  const o = decodeBankrV4LaunchOptions(p.options) ?? revert("InvalidOptions");
  const pad = state.pad ?? revert("UnknownLaunchpad");
  const x: Ctx = {
    s: state,
    pad,
    launcher: i.launcher,
    flags: pad.flags & state.allowedFlags,
    set: o.set | ALWAYS,
    o,
    kept: 0n,
    lp: false,
  };
  const t = emptyTerms();
  [t.launchpadId, t.quote, t.startTime] = [p.launchpadId, p.quote, p.startTime];
  owner(t, x);
  wiring(t, x);
  supplyAndVest(p, t, x);
  capAndSwitches(p, t, x);
  if ((p.devBuyAmountIn | i.nativeDevBuy) !== 0n) flag(x, F.devBuy);
  fees(p.econ, t, x);
  const padTerms = payees(p, t, x);
  works(t, x);
  stream(t, x);
  extension(p, t, x);
  start(p, t, x);
  curve(p.curveId, t, x);
  const resolvedHash = keccak256(encodeBankrV4CoinTerms(t));
  if (
    BigInt(o.expectedTermsHash) !== 0n &&
    o.expectedTermsHash.toLowerCase() !== resolvedHash
  ) {
    revert("TermsChanged", resolvedHash);
  }
  return { terms: t, resolvedHash, expectedToken: o.expectedToken, padTerms };
}
